      "weight": 0.20,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Adult cranial bones are fully fused and behave as rigid cortical bone; they cannot be compressed more than a few millimetres without fracturing.",
      "evidence": "Biomechanical properties of cortical bone and clinical data on skull fracture thresholds.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "Because the skull is both larger than the maximal pelvic opening and cannot be deformed enough without breaking, an intact adult skull cannot pass through the birth canal.",
      "evidence": "Logical synthesis of steps 3 and 4.",
      "weight": 0.10,
